// Ejecuta DENTRO de la carpeta movie-explorer-node:  node update.js
// Actualiza server.js y public. NO toca tu .env ni tu catalog.json si ya existe.
const fs = require("fs");
const path = require("path");
const files = {
  "server.js": "",
  "catalog.json": "ewogICJ0diI6IFs5MzQwNSwgOTQ3OTZdLAogICJtb3ZpZSI6IFtdCn0K",
  ".gitignore": "LmVudgpub2RlX21vZHVsZXMKbG9ncy5qc29uCnN1Ym1pc3Npb25zLmpzb24Kc2l0ZS5qc29uCg==",
  "public/index.html": "",
  "public/style.css": "",
  "public/app.js": "",
  "public/admin.html": "",
  "public/extras.js": ""
};
if (!fs.existsSync("package.json")) {
  console.error("Ejecuta este archivo dentro de la carpeta movie-explorer-node (donde esta package.json)");
  process.exit(1);
}
for (const [name, b64] of Object.entries(files)) {
  if ((name === "catalog.json" || name === ".gitignore") && fs.existsSync(name)) { console.log("Se mantiene tu", name); continue; }
  fs.mkdirSync(path.dirname(name), { recursive: true });
  fs.writeFileSync(name, Buffer.from(b64, "base64"));
  console.log("Actualizado:", name);
}
console.log("\nListo. Revisa tu .env y ejecuta: npm start");
